-- Seed exact closed summer assignments from כל פעילויות קיץ 25.xlsx.
insert into public.summer_feedback_cycles(cycle_key,title,activity_season,status,question_version,opens_at)
values('summer_2026','משוב פעילות הקיץ תשפ"ו','summer_2026','open',1,now())
on conflict(cycle_key) do update set title=excluded.title,activity_season=excluded.activity_season,status='open',
question_version=excluded.question_version,opens_at=coalesce(public.summer_feedback_cycles.opens_at,excluded.opens_at),updated_at=now();

