  as x(emp text,name text,activity text,type text,count integer,grades text[])
), resolved as (
  select c.id cycle_id,u.auth_user_id instructor_auth_user_id,s.*
  from seed s join public.users u on btrim(coalesce(u.emp_id,''))=s.emp and u.auth_user_id is not null and coalesce(u.is_active,false)
  cross join public.summer_feedback_cycles c where c.cycle_key='summer_2026'
)
insert into public.summer_feedback_assignments(
  cycle_id,instructor_auth_user_id,instructor_emp_id,instructor_name,activity_key,activity_name,activity_type,activity_count,grade_labels,source_note
)
select cycle_id,instructor_auth_user_id,emp,name,md5(activity),activity,type,count,grades,
  'כל פעילויות קיץ 25.xlsx — רשומות במצב סגור' from resolved
on conflict(cycle_id,instructor_auth_user_id,activity_key) do update set
  instructor_emp_id=excluded.instructor_emp_id,instructor_name=excluded.instructor_name,activity_name=excluded.activity_name,
  activity_type=excluded.activity_type,activity_count=excluded.activity_count,grade_labels=excluded.grade_labels,source_note=excluded.source_note;

do $$
declare assignment_rows integer; activity_total integer; instructor_total integer;
begin
  select count(*),coalesce(sum(a.activity_count),0),count(distinct a.instructor_auth_user_id)
  into assignment_rows,activity_total,instructor_total
  from public.summer_feedback_assignments a join public.summer_feedback_cycles c on c.id=a.cycle_id where c.cycle_key='summer_2026';
  if assignment_rows<>59 or activity_total<>291 or instructor_total<>10 then
    raise exception 'summer feedback seed mismatch: assignments=%, activities=%, instructors=%',assignment_rows,activity_total,instructor_total;
  end if;
end $$;
notify pgrst,'reload schema';
